alternatives.grammar_source:
| NUMBER64BIT
	{
		SINT64 signedNumber = (SINT64) $1.number;

		if ($1.hex && signedNumber < 0)
			$$ = newNode<NegateNode>(MAKE_const_sint64(-signedNumber, $1.scale));
		else
			$$ = MAKE_const_sint64(signedNumber, $1.scale);
	}

